package org.jetlinks.sdk.client;

import static org.junit.jupiter.api.Assertions.*;

import org.jetlinks.sdk.client.auth.LocalToken;
import org.jetlinks.sdk.client.crypto.*;
import org.jetlinks.sdk.client.notification.*;
import org.junit.jupiter.api.Test;

import reactor.core.publisher.Mono;

import java.nio.charset.StandardCharsets;
import java.time.*;
import java.util.*;

class ProtocolTest {
    static final String SECRET = "test-secret-abcdefghijklmnopqrstuvwxyz";
    static final long TIME = 1780000000000L;

    // Independently generated by the platform's Node reference; not sign-then-verify using SDK
    // implementation.
    @Test
    void localTokenIndependentVectors() {
        assertEquals(
                "at_fLBknmXyvZGenUvtjnoF9mvAeBJGhR6DfNS8meOQ2OtU2sr0RQqkBmae",
                LocalToken.create("client-1", SECRET, null, TIME));
        assertEquals(
                "at_fLBknmXyvZGenUvtjnoF9mvAeBJGirDjudjeAvbVmrsrCdZA6LEqV2s7",
                LocalToken.create("client-1", SECRET, Collections.emptyList(), TIME));
        assertEquals(
                "at_kkhBl0tChesoMiEHgD84lqxD8EXOXyMOqXSDmFkJOAhGcebjMtjlBWWXghCze1qu",
                LocalToken.create("client-1", SECRET, Arrays.asList("b", "a", "b"), TIME));
    }

    static Map<String, List<String>> headers() {
        Map<String, List<String>> h = new LinkedHashMap<>();
        h.put("X-Signature-Version", Collections.singletonList("1"));
        h.put("X-Application-Id", Collections.singletonList("app-1"));
        h.put("X-Key-Id", Collections.singletonList("client-1"));
        h.put("X-Timestamp", Collections.singletonList(Long.toString(TIME)));
        h.put("X-Event-Id", Collections.singletonList("event-1"));
        h.put(
                "X-Signature",
                Collections.singletonList("YqDo1DVgtopiw-BBoq7hly83YleKdDS2KABSTlJ1ULE"));
        return h;
    }

    static byte[] body() {
        return "{\"id\":\"event-1\",\"type\":\"device.online\",\"data\":{\"message\":\"你好\"}}"
                .getBytes(StandardCharsets.UTF_8);
    }

    static NotificationVerifier verifier() {
        return new NotificationVerifier(
                (p, a, k) -> Mono.just(TrustedKey.api("app-1", SECRET)),
                Clock.fixed(Instant.ofEpochMilli(TIME), ZoneOffset.UTC),
                Duration.ofMinutes(5));
    }

    @Test
    void independentNotificationVector() {
        VerifiedNotification n = verifier().verify(headers(), body()).block();
        assertEquals("app-1", n.applicationId);
        assertEquals("", n.platformId);
        assertEquals("你好", n.event.data.get("message"));
    }

    @Test
    void tamperAndDuplicateHeadersFail() {
        Map<String, List<String>> h = headers();
        h.put("x-application-id", Collections.singletonList("other"));
        assertEquals(
                SdkException.Code.AUTHENTICATION,
                assertThrows(SdkException.class, () -> verifier().verify(h, body()).block()).code);
        assertThrows(
                SdkException.class,
                () -> verifier().verify(headers(), "{}".getBytes(StandardCharsets.UTF_8)).block());
        Map<String, List<String>> platform = headers();
        platform.put("X-Platform-Id", Collections.singletonList("region"));
        assertThrows(SdkException.class, () -> verifier().verify(platform, body()).block());
    }

    @Test
    void apiDataDoesNotSelectBusinessChannel() {
        byte[] bytes =
                "{\"id\":\"event-1\",\"type\":\"application.created\",\"data\":{\"application\":{\"id\":\"arbitrary\"}}}"
                        .getBytes(StandardCharsets.UTF_8);
        Map<String, List<String>> h = headers();
        h.put(
                "X-Signature",
                Collections.singletonList(
                        Signatures.sign(
                                SECRET,
                                "1",
                                "app-1",
                                "",
                                "client-1",
                                Long.toString(TIME),
                                "event-1",
                                Signatures.sha256(bytes))));
        assertEquals("app-1", verifier().verify(h, bytes).block().applicationId);
    }
}
